-- Table: ms_ter
CREATE TABLE ms_ter (
    id INT PRIMARY KEY,
    ptkp_name VARCHAR(50) NOT NULL,
    ter_type VARCHAR(10) NOT NULL
);


-- Table: ms_ter_fee
CREATE TABLE ms_ter_fee (
    id INT PRIMARY KEY,
    ter_type VARCHAR(10) NOT NULL,
    fee_from BIGINT NOT NULL,
    fee_until BIGINT NOT NULL,
    amount_in_percent NUMERIC(5,2) NOT NULL
);

